from langchain_core.messages import SystemMessage
from src.github_repo_parser import GitRepoParser

async def fetch_repo_metadata_node(state: dict) -> dict:
    """
    First node of the workflow:
    - Reads repository URL from state['url']
    - Optionally reads state['branch'] and state['refresh_cache']
    - Calls GitRepoParser to get metadata tree (with disk caching)
    - Updates state with repo_tree
    """

    repo_url = state.get("url", None)
    if not repo_url:
        return {
            "messages": state["messages"] + [
                SystemMessage(content="No repository URL provided.")
            ]
        }

    branch = state.get("branch") or None
    refresh = bool(state.get("refresh_cache", False))

    try:
        parser = GitRepoParser()
        repo_tree = parser.get_dir_tree(repo_url, branch=branch, refresh=refresh)

        return {
            "repo_tree": repo_tree,
            "messages": state["messages"] + [
                SystemMessage(content=f"Fetched metadata tree for: {repo_url}")
            ]
        }

    except PermissionError as e:
        # GitHub rate limit or auth errors
        err = str(e)
        print(err)
        return {
            "repo_tree": {},
            "messages": state["messages"] + [
                SystemMessage(content=err)
            ]
        }

    except ValueError as e:
        # Bad URL or 404
        err = str(e)
        print(err)
        return {
            "repo_tree": {},
            "messages": state["messages"] + [
                SystemMessage(content=err)
            ]
        }

    except Exception as e:
        err = f"Error fetching repository metadata: {e}"
        print(err)
        return {
            "repo_tree": {},
            "messages": state["messages"] + [
                SystemMessage(content=err)
            ]
        }

def parse_notebook(raw: str) -> str:
    """
    Extracts markdown + code cells from a .ipynb file.
    Converts them to readable text for LLMs.
    """

    try:
        import nbformat

        nb = nbformat.reads(raw, as_version=4)
    except Exception:
        return raw[:5000]

    out = []

    for cell in nb.cells:
        if cell.cell_type == "markdown":
            out.append("## Markdown Cell:\n" + cell.source)
        elif cell.cell_type == "code":
            out.append("## Code Cell:\n" + cell.source)
    # print(f"Checking Execution of parse_notebook tool: {out}")

    return "\n\n".join(out)[:8000]

import ast

def parse_python(raw: str) -> str:
    """
    Extracts imports, classes, functions, and docstrings from a Python file.
    Returns a clean textual summary.
    """

    try:
        tree = ast.parse(raw)
    except Exception:
        # If AST fails (bad syntax), return cleaned raw text
        return _clean_raw_python(raw)

    imports = []
    functions = []
    classes = []
    docstrings = {}

    for node in ast.walk(tree):

        # Imports
        if isinstance(node, ast.Import):
            for alias in node.names:
                imports.append(alias.name)

        if isinstance(node, ast.ImportFrom):
            if node.module:
                imports.append(node.module)

        # Functions
        if isinstance(node, ast.FunctionDef):
            functions.append(node.name)
            docstrings[node.name] = ast.get_docstring(node) or ""

        # Classes
        if isinstance(node, ast.ClassDef):
            classes.append(node.name)
            docstrings[node.name] = ast.get_docstring(node) or ""

    summary = []

    if imports:
        summary.append("## Imports:\n" + "\n".join(f"- {i}" for i in imports))

    if classes:
        summary.append("## Classes:\n" + "\n".join(f"- {c}" for c in classes))

    if functions:
        summary.append("## Functions:\n" + "\n".join(f"- {f}" for f in functions))

    if docstrings:
        summary.append("## Docstrings:\n")
        for name, doc in docstrings.items():
            if doc:
                summary.append(f"### {name}\n{doc}\n")

    # Return readable summary
    # print(f"Summary Debug 2: {summary}")
    return "\n".join(summary) or _clean_raw_python(raw)


def _clean_raw_python(raw: str):
    """
    Fallback: remove excessive whitespace and comments.
    """
    cleaned = []
    for line in raw.splitlines():
        if line.strip().startswith("#"):
            continue
        cleaned.append(line)
    return "\n".join(cleaned)

def summarize_state(state):
    out = {}
    for k, v in state.items():
        if isinstance(v, (list, tuple, set)):
            out[k] = f"<{type(v).__name__}> len={len(v)}"
        elif isinstance(v, dict):
            out[k] = f"<dict> keys={list(v.keys())[:5]} (total={len(v)})"
        else:
            out[k] = f"{type(v).__name__}: {str(v)[:80]}..."
    return out

